BEGIN;
-- Source: Constituição Unificada do GOV.RP (9 pages), supplied by project owner.
-- Preserve the original 1.0 constitution and its article IDs as archived history.
ALTER TABLE public.country_constitutions
  ADD COLUMN IF NOT EXISTS closing_text text NOT NULL DEFAULT '';

UPDATE public.country_constitutions
SET status='superseded', superseded_at=COALESCE(superseded_at,clock_timestamp()), updated_at=clock_timestamp()
WHERE country_code='BR' AND status='active' AND version<>'2.0';

DO $govrp_unified$
DECLARE
  v_id uuid;
  v_section_id uuid;
  v_section jsonb;
  v_article jsonb;
  v_sections jsonb := $govrp_document_json$[{"title":"TÍTULO I — DOS PRINCÍPIOS FUNDAMENTAIS","sort_order":10,"articles":[{"article_number":"Art. 1º","sort_order":10,"body":"A República Federativa do Brasil, no âmbito do GOV.RP, constitui-se em Estado soberano, democrático, representativo e de governo presidencialista."},{"article_number":"Art. 2º","sort_order":20,"body":"São fundamentos da República a soberania, a cidadania, a dignidade da pessoa humana, os valores sociais do trabalho e da livre iniciativa e o pluralismo político."},{"article_number":"Art. 3º","sort_order":30,"body":"São objetivos fundamentais da República construir uma sociedade livre, justa e solidária; promover o desenvolvimento nacional; reduzir a pobreza e as desigualdades sociais e regionais; e promover o bem de todos, sem discriminação."},{"article_number":"Art. 4º","sort_order":40,"body":"Todo poder emana do povo, que o exerce por meio de representantes eleitos e pelos mecanismos de participação direta previstos nesta Constituição e na legislação aplicável."},{"article_number":"Art. 5º","sort_order":50,"body":"São Poderes da União, independentes e harmônicos entre si, o Executivo, o Legislativo e o Judiciário. Nenhum Poder exercerá atribuições próprias de outro, salvo nas hipóteses expressamente previstas nesta Constituição."}]},{"title":"TÍTULO II — DOS DIREITOS E GARANTIAS FUNDAMENTAIS","sort_order":20,"articles":[{"article_number":"Art. 6º","sort_order":10,"body":"Todos são iguais perante a lei. São assegurados aos cidadãos e, nos termos da lei, às demais pessoas sob a jurisdição da República, os direitos à vida, à liberdade, à igualdade, à segurança, à dignidade e à propriedade."},{"article_number":"Art. 7º","sort_order":20,"body":"São garantidas a liberdade de pensamento, expressão, consciência, crença e opinião; a expressão intelectual, artística, científica e de comunicação; a reunião pacífica; e a associação para fins lícitos, vedado o anonimato nos termos da lei."},{"article_number":"Art. 8º","sort_order":30,"body":"São invioláveis a intimidade, a vida privada, a honra, a imagem, o domicílio e o sigilo das comunicações, ressalvadas as hipóteses legais e as decisões judiciais cabíveis."},{"article_number":"Art. 9º","sort_order":40,"body":"É livre o exercício de trabalho, ofício ou profissão, observadas as qualificações previstas em lei. É assegurada a liberdade de locomoção em tempo de paz, nos termos legais."},{"article_number":"Art. 10.","sort_order":50,"body":"O direito de propriedade é garantido e deverá atender à sua função social."},{"article_number":"Art. 11.","sort_order":60,"body":"Todos têm direito a obter dos órgãos públicos informações de interesse particular, coletivo ou geral, ressalvado o sigilo legalmente necessário à segurança da sociedade e do Estado."},{"article_number":"Art. 12.","sort_order":70,"body":"A lei não excluirá da apreciação do Poder Judiciário lesão ou ameaça a direito, nem prejudicará o direito adquirido, o ato jurídico perfeito ou a coisa julgada."},{"article_number":"Art. 13.","sort_order":80,"body":"Ninguém será obrigado a fazer ou deixar de fazer algo senão em virtude de lei. Ninguém será privado da liberdade ou de seus bens sem o devido processo legal, assegurados o contraditório e a ampla defesa nos processos judiciais e administrativos."},{"article_number":"Art. 14.","sort_order":90,"body":"Não há crime sem lei anterior que o defina, nem pena sem prévia previsão legal. A lei penal não retroagirá, salvo para beneficiar o acusado. Ninguém será considerado culpado antes do trânsito em julgado de sentença penal condenatória."},{"article_number":"Art. 15.","sort_order":100,"body":"São vedadas penas cruéis, de caráter perpétuo, de trabalhos forçados e de banimento. A pena de morte somente poderá ser admitida na hipótese de guerra declarada, conforme a lei."},{"article_number":"Art. 16.","sort_order":110,"body":"A pessoa presa será informada de seus direitos, inclusive o de permanecer calada, e terá assegurado o acesso à assistência de sua família e de advogado. O Estado indenizará quem sofrer condenação por erro judiciário ou permanecer preso além do tempo fixado na sentença."},{"article_number":"Art. 17.","sort_order":120,"body":"Nenhuma pessoa será privada de direitos sem fundamento legal e decisão da autoridade competente. São assegurados o acesso aos serviços públicos e a igualdade de tratamento perante as instituições do GOV.RP."}]},{"title":"TÍTULO III — DA ORGANIZAÇÃO POLÍTICA E DA PARTICIPAÇÃO POPULAR","sort_order":30,"articles":[{"article_number":"Art. 18.","sort_order":10,"body":"O Presidente da República exerce a chefia de Estado e de Governo, nos termos desta Constituição."},{"article_number":"Art. 19.","sort_order":20,"body":"O Parlamento, organizado na forma desta Constituição e das normas próprias, representa a vontade popular, delibera sobre projetos, fiscaliza o Poder Executivo e exerce as demais competências legislativas."},{"article_number":"Art. 20.","sort_order":30,"body":"O povo poderá apresentar sugestões de projetos, participar de consultas públicas e propor a realização de plebiscitos, na forma da legislação aplicável."},{"article_number":"Art. 21.","sort_order":40,"body":"O voto é instrumento legítimo de escolha dos representantes e de definição dos rumos políticos da República. As eleições serão realizadas por voto direto e secreto, nos termos da lei."}]},{"title":"TÍTULO IV — DO PODER EXECUTIVO","sort_order":40,"articles":[{"article_number":"Art. 22.","sort_order":10,"body":"O Poder Executivo é exercido pelo Presidente da República, auxiliado pelos Ministros de Estado."},{"article_number":"Art. 23.","sort_order":20,"body":"O Presidente será eleito por voto direto e secreto para mandato de quatro anos, correspondente a vinte e oito dias no calendário do RP, permitida uma única reeleição consecutiva."},{"article_number":"Art. 24.","sort_order":30,"body":"Compete ao Presidente da República:\nI — nomear e exonerar Ministros de Estado;\nII — sancionar, promulgar e vetar leis;\nIII — representar a República nas relações exteriores;\nIV — decretar estado de defesa e estado de sítio, observadas as condições desta Constituição;\nV — zelar pela ordem pública, pela segurança e pelo cumprimento da Constituição;\nVI — nomear o Diretor da AGIES, os diretores dos três departamentos policiais e, nos termos previstos nesta Constituição, os oficiais-generais indicados para funções de comando;\nVII — propor ou autorizar, dentro de sua competência e conforme a legislação tributária, ajustes de impostos incidentes sobre serviços básicos, com vistas ao equilíbrio econômico, social e financeiro."},{"article_number":"Art. 25.","sort_order":40,"body":"O Presidente poderá responder a processo de impeachment por crime de responsabilidade. A denúncia dependerá de aprovação pela maioria absoluta da Câmara dos Deputados, e o julgamento caberá ao Senado Federal, sob a presidência do Presidente do Supremo Tribunal Federal, observada a legislação aplicável."},{"article_number":"Art. 25-A","sort_order":50,"body":"Dos crimes de responsabilidade\n Constituem crimes de responsabilidade do Presidente da República os atos que atentem contra esta Constituição, especialmente:\nI — atentar contra a existência da República, a soberania nacional ou a integridade territorial;\nII — impedir o livre exercício do Poder Legislativo ou do Poder Judiciário;\nIII — violar direitos e garantias fundamentais ou utilizar o cargo para perseguir adversários políticos;\nIV — praticar corrupção, peculato, desvio de recursos públicos ou enriquecimento ilícito relacionado ao exercício do cargo;\nV — obstruir investigações, destruir provas ou utilizar órgãos públicos para impedir a apuração de irregularidades;\nVI — descumprir deliberadamente as leis orçamentárias, ocultar despesas públicas ou utilizar recursos da União para fins particulares ou ilícitos;\nVII — interferir ilegalmente nas eleições, fraudar resultados ou impedir a posse de autoridades legitimamente eleitas;\nVIII — utilizar as Forças Armadas, as polícias ou a AGIES para fins particulares, partidários ou para subverter a ordem constitucional;\nIX — descumprir deliberadamente decisões judiciais definitivas ou impedir o cumprimento de leis regularmente aprovadas;\nX — praticar outros atos definidos em lei como crimes de responsabilidade."},{"article_number":"Art. 25-B","sort_order":60,"body":"Da apresentação da denúncia\n A denúncia contra o Presidente da República poderá ser apresentada por qualquer cidadão que possua capacidade civil e deverá conter a descrição dos fatos, os fundamentos jurídicos e os elementos de prova disponíveis.\n§ 1º A denúncia será encaminhada à Câmara dos Deputados, que verificará sua admissibilidade formal.\n§ 2º A denúncia manifestamente infundada, sem descrição de conduta imputável ao Presidente ou desacompanhada de elementos mínimos que justifiquem sua apuração poderá ser rejeitada mediante decisão fundamentada.\n§ 3º A rejeição da denúncia não impedirá a apresentação de nova denúncia baseada em fatos ou provas diferentes."},{"article_number":"Art. 25-C","sort_order":70,"body":"Da admissibilidade do impeachment\n Recebida a denúncia, o Presidente da Câmara dos Deputados determinará sua análise por comissão especial, assegurando ao Presidente da República o direito de apresentar defesa.\n§ 1º A comissão especial emitirá parecer fundamentado, recomendando o prosseguimento ou o arquivamento do processo.\n§ 2º A abertura do processo dependerá do voto favorável da maioria absoluta dos membros da Câmara dos Deputados.\n§ 3º A decisão deverá ser nominal e pública, ressalvadas as informações legalmente sigilosas."},{"article_number":"Art. 25-D","sort_order":80,"body":"Do julgamento pelo Senado Federal\n Admitida a acusação pela Câmara dos Deputados, caberá ao Senado Federal processar e julgar o Presidente da República, sob a presidência do Presidente do Supremo Tribunal Federal.\n§ 1º O Presidente da República terá direito à ampla defesa, ao contraditório, à apresentação de provas e à assistência jurídica.\n§ 2º A condenação dependerá do voto favorável de dois terços dos membros do Senado Federal.\n§ 3º A decisão deverá ser fundamentada e publicada oficialmente.\n§ 4º A absolvição encerrará o processo de impeachment, sem impedir eventual responsabilização criminal ou civil pelos mesmos fatos, quando cabível."},{"article_number":"Art. 25-E","sort_order":90,"body":"Dos efeitos do impeachment\n A condenação em processo de impeachment resultará na perda do cargo de Presidente da República e poderá acarretar inabilitação para o exercício de função pública por até oito anos, conforme a gravidade dos fatos e mediante decisão expressa.\nParágrafo único. O impeachment não exclui a aplicação de sanções civis, administrativas ou penais cabíveis, observados os procedimentos próprios."},{"article_number":"Art. 25-F","sort_order":100,"body":"Do afastamento e da sucessão presidencial\n O Presidente da República não será afastado definitivamente em razão da mera apresentação de denúncia.\n§ 1º O afastamento temporário durante o processo somente poderá ocorrer nas hipóteses e pelo prazo previstos em lei, mediante decisão fundamentada da autoridade competente.\n§ 2º Em caso de condenação, vacância, renúncia ou impedimento definitivo, a sucessão presidencial obedecerá à ordem estabelecida nesta Constituição e na legislação eleitoral.\n§ 3º É vedado utilizar o processo de impeachment como instrumento de perseguição política ou como substituto das eleições regulares."},{"article_number":"Art. 25-G","sort_order":110,"body":"Da responsabilidade dos Ministros de Estado\n Os Ministros de Estado responderão pelos atos praticados no exercício de suas funções, inclusive por corrupção, desvio de recursos públicos, abuso de autoridade, violação constitucional e omissão deliberada no cumprimento de seus deveres.\n§ 1º O Presidente da República poderá exonerar livremente os Ministros de Estado, sem prejuízo de eventual responsabilização civil, administrativa ou penal.\n§ 2º A Câmara dos Deputados poderá convocar Ministros para prestar esclarecimentos sobre assuntos relacionados às suas pastas, observadas as regras regimentais.\n§ 3º A recusa injustificada em comparecer, a prestação deliberada de informações falsas ou a obstrução da fiscalização parlamentar sujeitará o responsável às sanções previstas em lei.\n§ 4º A responsabilidade criminal dos Ministros será apurada perante a autoridade judicial competente, respeitadas as competências constitucionais do Supremo Tribunal Federal."},{"article_number":"Art. 25-H","sort_order":120,"body":"Da moção de censura política\n A Câmara dos Deputados poderá aprovar moção de censura contra Ministro de Estado ou manifestar formalmente sua desaprovação à condução política do Poder Executivo.\n§ 1º A moção de censura deverá ser apresentada por, no mínimo, um quinto dos membros da Câmara dos Deputados e submetida à votação em sessão pública.\n§ 2º A aprovação dependerá da maioria absoluta dos membros da Câmara.\n§ 3º A moção de censura não implicará automaticamente a exoneração do Ministro nem a destituição do Presidente da República, mas obrigará o Ministro censurado a prestar esclarecimentos à Câmara no prazo previsto em lei.\n§ 4º O Presidente da República deverá responder formalmente às conclusões da Câmara, podendo manter ou exonerar o Ministro, mediante comunicação institucional.\n§ 5º A moção de censura não poderá ser utilizada para suspender a vigência de leis, impedir a execução do orçamento aprovado ou afastar autoridades fora dos procedimentos constitucionais."}]},{"title":"TÍTULO V — DO PODER LEGISLATIVO","sort_order":50,"articles":[{"article_number":"Art. 26.","sort_order":10,"body":"O Poder Legislativo é exercido pelo Congresso Nacional, composto pela Câmara dos Deputados e pelo Senado Federal."},{"article_number":"Art. 27.","sort_order":20,"body":"Compete ao Congresso Nacional:\nI — elaborar, discutir e aprovar leis e emendas constitucionais;\nII — fiscalizar os atos do Poder Executivo;\nIII — deliberar sobre operações financeiras e tratados internacionais, conforme a lei;\nIV — apreciar e aprovar o orçamento anual da União;\nV — processar e julgar, nos casos previstos nesta Constituição, o Presidente da República e Ministros por crimes de responsabilidade;\nVI — deliberar sobre projetos e plebiscitos nos termos constitucionais e legais."},{"article_number":"Art. 28.","sort_order":30,"body":"Deputados e Senadores representam, respectivamente, o povo e os entes políticos representados no Senado, gozando de imunidade parlamentar nos termos da lei."}]},{"title":"TÍTULO VI — DO PODER JUDICIÁRIO","sort_order":60,"articles":[{"article_number":"Art. 29.","sort_order":10,"body":"O Poder Judiciário é independente e tem por missão interpretar e aplicar as leis, proteger direitos, solucionar conflitos e defender a supremacia desta Constituição."},{"article_number":"Art. 30.","sort_order":20,"body":"O Supremo Tribunal Federal (STF) é o órgão máximo do Poder Judiciário e será composto por três Ministros, nomeados pelo Presidente da República após aprovação pela maioria absoluta do Senado Federal."},{"article_number":"Art. 31.","sort_order":30,"body":"Compete ao STF:\nI — julgar ações de inconstitucionalidade e conflitos entre os Poderes;\nII — processar e julgar, nos casos previstos em lei, o Presidente da República, os Ministros de Estado e outras autoridades políticas federais por crimes comuns;\nIII — assegurar a supremacia da Constituição e a harmonia entre os Poderes;\nIV — apreciar a constitucionalidade de alterações dos regimentos internos dos Poderes, conforme o art. 45."},{"article_number":"Art. 32.","sort_order":40,"body":"Os Ministros do STF perderão o cargo por sentença judicial transitada em julgado, aposentadoria voluntária ou impeachment aprovado por dois terços do Congresso Nacional, em caso de conduta incompatível com a dignidade do cargo, corrupção ou abuso de autoridade."},{"article_number":"Art. 33.","sort_order":50,"body":"Lei complementar, de iniciativa do STF, disporá sobre o Estatuto da Magistratura, observando o ingresso na carreira inicial de juiz substituto mediante concurso público de provas e títulos, com participação da Ordem dos Advogados do Brasil em todas as fases; a promoção alternada por antiguidade e merecimento; e as garantias de vitaliciedade, inamovibilidade, salvo por interesse público, e irredutibilidade de subsídio."},{"article_number":"Art. 34.","sort_order":60,"body":"Os julgamentos serão públicos e as decisões fundamentadas, sob pena de nulidade, admitidas restrições legais de acesso em atos específicos para proteção das partes e de informações legalmente sigilosas."}]},{"title":"TÍTULO VII — DA ADMINISTRAÇÃO PÚBLICA","sort_order":70,"articles":[{"article_number":"Art. 35.","sort_order":10,"body":"A administração pública direta e indireta obedecerá aos princípios da legalidade, impessoalidade, moralidade, publicidade e eficiência."},{"article_number":"Art. 36.","sort_order":20,"body":"O ingresso em cargos públicos dependerá de mérito, qualificação e idoneidade, observados os requisitos legais."},{"article_number":"Art. 37.","sort_order":30,"body":"O desvio de recursos públicos, a corrupção e o abuso de poder sujeitam seus responsáveis às sanções previstas em lei. A classificação como crimes inafiançáveis ou imprescritíveis dependerá de previsão constitucional e legal aplicável."},{"article_number":"Art. 37-A","sort_order":40,"body":"Da transparência e fiscalização fiscal\n A gestão dos recursos públicos observará os princípios da legalidade, transparência, eficiência, responsabilidade fiscal e prestação de contas.\n§ 1º O Poder Executivo deverá apresentar ao Congresso Nacional relatórios periódicos de execução orçamentária, arrecadação, despesas, endividamento e cumprimento das metas fiscais.\n§ 2º O Congresso Nacional exercerá o controle externo das contas públicas, com auxílio do órgão de controle externo competente, na forma da lei.\n§ 3º As despesas públicas, contratos, transferências e operações de crédito deverão ser registrados e disponibilizados para fiscalização, ressalvadas as informações cujo sigilo seja legalmente necessário.\n§ 4º A identificação de irregularidades poderá resultar em auditoria, investigação, determinação de correções e encaminhamento às autoridades competentes.\n§ 5º Nenhuma autoridade poderá impedir a fiscalização legalmente autorizada, destruir documentos contábeis ou retaliar agentes públicos que comuniquem irregularidades de boa-fé."}]},{"title":"TÍTULO VIII — DA ORDEM ECONÔMICA E SOCIAL","sort_order":80,"articles":[{"article_number":"Art. 38.","sort_order":10,"body":"A ordem econômica funda-se na valorização do trabalho humano, na livre iniciativa, na função social e na responsabilidade fiscal do Estado, devendo buscar existência digna para todos e desenvolvimento nacional."},{"article_number":"Art. 39.","sort_order":20,"body":"O Estado atuará como regulador da economia e promotor da estabilidade financeira. A atividade econômica é livre, respeitados o interesse público, a função social e a soberania nacional."},{"article_number":"Art. 40.","sort_order":30,"body":"O Estado promoverá progressivamente educação, saúde, segurança, infraestrutura e acesso digital, observadas as prioridades públicas, a disponibilidade orçamentária e a legislação aplicável."},{"article_number":"Art. 41.","sort_order":40,"body":"São considerados serviços básicos essenciais no GOV.RP: internet, energia elétrica, água, telefonia, aluguel, serviços de manutenção essenciais e gás."},{"article_number":"Art. 42.","sort_order":50,"body":"O Estado regulamentará a prestação dos serviços básicos. Os tributos incidentes sobre esses serviços poderão ser ajustados pelo Presidente dentro de sua competência e conforme a legislação tributária."},{"article_number":"Art. 43.","sort_order":60,"body":"Nenhum serviço básico poderá ser suspenso sem aviso prévio ou justificativa legal, salvo em situação de emergência. As empresas prestadoras deverão observar transparência, qualidade e direitos dos consumidores. Legislação complementar poderá definir tarifas, fiscalização e padrões mínimos."}]},{"title":"TÍTULO IX — DA DEFESA DO ESTADO E DAS INSTITUIÇÕES DEMOCRÁTICAS","sort_order":90,"articles":[{"article_number":"Art. 44.","sort_order":10,"body":"O estado de defesa e o estado de sítio poderão ser decretados pelo Presidente da República, com autorização do Congresso Nacional, para preservar a ordem pública ou restabelecer a paz ameaçada. Eventuais restrições de direitos deverão ser temporárias e limitadas ao estritamente necessário.\nParágrafo único. Nenhuma autoridade poderá suspender esta Constituição, inclusive sob alegação de urgência, conflito ou guerra."}]},{"title":"TÍTULO X — DAS FORÇAS ARMADAS","sort_order":100,"articles":[{"article_number":"Art. 45.","sort_order":10,"body":"As Forças Armadas são instituições permanentes, constituídas pelo Exército, pela Marinha e pela Força Aérea, sob a autoridade suprema do Presidente da República, Comandante Supremo das Forças Armadas."},{"article_number":"Art. 46.","sort_order":20,"body":"Compete ao Exército proteger o território contra ameaças externas, apoiar a defesa civil em calamidades, colaborar com as autoridades federais no cumprimento da Constituição e das leis e executar operações de garantia da lei e da ordem quando solicitado pelo Presidente, nos termos legais."},{"article_number":"Art. 47.","sort_order":30,"body":"O Presidente poderá nomear três Generais do Exército. A hierarquia e a disciplina militares serão reguladas por leis específicas."},{"article_number":"Art. 48.","sort_order":40,"body":"As Forças Armadas não poderão suspender a Constituição nem praticar atos que violem os direitos e garantias fundamentais."}]},{"title":"TÍTULO XI — DAS POLÍCIAS E DA SEGURANÇA PÚBLICA","sort_order":110,"articles":[{"article_number":"Art. 49.","sort_order":10,"body":"A segurança pública é dever do Estado e direito de todos, destinada à preservação da ordem pública, da paz social e à proteção das pessoas e do patrimônio."},{"article_number":"Art. 50.","sort_order":20,"body":"Compete:\nI — à Polícia Federal, investigar e reprimir crimes federais, controlar fronteiras, aeroportos e portos e garantir a segurança de autoridades;\nII — às Polícias Estaduais, manter a ordem, prevenir e investigar crimes em seus territórios;\nIII — às Polícias Municipais ou Guardas Municipais, proteger bens, serviços e instalações públicas municipais."},{"article_number":"Art. 51.","sort_order":30,"body":"O Presidente da República poderá nomear os diretores dos três departamentos policiais. As polícias observarão os princípios da legalidade, impessoalidade, moralidade, publicidade e eficiência."},{"article_number":"Art. 52.","sort_order":40,"body":"As prisões dependerão de flagrante delito ou de ordem judicial fundamentada, ressalvadas as hipóteses legais, inclusive a captura durante fuga. Nenhuma autoridade policial poderá suspender esta Constituição ou atuar contra o Estado Democrático de Direito."}]},{"title":"TÍTULO XII — DOS PARTIDOS POLÍTICOS","sort_order":120,"articles":[{"article_number":"Art. 53.","sort_order":10,"body":"É livre a criação e o funcionamento de partidos políticos, observados os princípios democráticos, a soberania popular e esta Constituição."},{"article_number":"Art. 54.","sort_order":20,"body":"A criação de partido no RP exige quatro assinaturas de membros fundadores, sendo uma do líder e três de outros membros. O partido deverá registrar-se perante o órgão competente e observar os requisitos legais de filiação e representatividade."},{"article_number":"Art. 55.","sort_order":30,"body":"Cada partido manterá estatuto, programa político e órgãos de direção, com transparência e participação democrática de seus membros. É vedada a atuação partidária voltada à supressão da democracia ou à violação dos direitos fundamentais."},{"article_number":"Art. 56.","sort_order":40,"body":"A extinção de partido por descumprimento constitucional ou legal será decidida pelo STF, mediante procedimento que assegure o devido processo legal."}]},{"title":"TÍTULO XIII — DA AGIES","sort_order":130,"articles":[{"article_number":"Art. 57.","sort_order":10,"body":"A Agência de Inteligência e Espionagem Suprema (AGIES) é o órgão destinado a coletar, analisar e coordenar informações estratégicas para a segurança nacional e a defesa do Estado."},{"article_number":"Art. 58.","sort_order":20,"body":"A AGIES atua sob supervisão direta do Presidente da República. O Presidente nomeará seu Diretor, responsável pela direção das operações e pela prestação de contas ao Poder Executivo."},{"article_number":"Art. 59.","sort_order":30,"body":"Compete à AGIES coletar e analisar informações sobre ameaças internas e externas; apoiar a Presidência e as Forças Armadas na defesa nacional; realizar atividades de inteligência, espionagem e contraespionagem; e colaborar com os órgãos de segurança pública e defesa do Estado."},{"article_number":"Art. 60.","sort_order":40,"body":"As atividades da AGIES deverão respeitar a Constituição e os direitos fundamentais, e estar sujeitas a justificativa e supervisão, mesmo quando sigilosas. O Diretor poderá ser destituído pelo Presidente e responderá perante o STF por abuso de poder, corrupção ou violação constitucional."},{"article_number":"Art. 61.","sort_order":50,"body":"Havendo suspeita de irregularidade ou de violação constitucional, o Presidente do STF poderá solicitar informações detalhadas sobre operações da AGIES. Na ausência de irregularidades, deverá ser preservado o sigilo das informações recebidas."}]},{"title":"TÍTULO XIV — DA IDENTIFICAÇÃO CIVIL","sort_order":140,"articles":[{"article_number":"Art. 62.","sort_order":10,"body":"A identificação civil é obrigatória para cidadãos brasileiros e residentes legais e será composta pelo Cadastro de Pessoa Física (CPF) e pelo Registro Geral (RG), conforme a legislação aplicável."},{"article_number":"Art. 63.","sort_order":20,"body":"O CPF será utilizado para fins fiscais, tributários e de identificação em serviços públicos e privados. O RG comprovará a identidade e conterá os dados pessoais essenciais, com validade em todo o território nacional."},{"article_number":"Art. 64.","sort_order":30,"body":"O Estado garantirá a emissão, a atualização e a segurança dos dados de identificação. Ninguém poderá ser privado de serviços ou direitos básicos exclusivamente pela ausência de CPF ou RG. Legislação complementar disciplinará emissão, validade, segurança e utilização."}]},{"title":"TÍTULO XV — DOS REGIMENTOS DOS PODERES","sort_order":150,"articles":[{"article_number":"Art. 65.","sort_order":10,"body":"Após a publicação do primeiro regimento interno de cada Poder da União, qualquer alteração subsequente somente terá validade após aprovação pelo Congresso Nacional, exame de constitucionalidade pelo STF e sanção do Presidente da República."}]},{"title":"TÍTULO XVI — DAS EMENDAS CONSTITUCIONAIS E DAS CLÁUSULAS PÉTREAS","sort_order":160,"articles":[{"article_number":"Art. 66.","sort_order":10,"body":"Esta Constituição poderá ser alterada por emenda, observado o rito legislativo próprio de 3/5 em cada casa, e o interesse nacional."},{"article_number":"Art. 67.","sort_order":20,"body":"Não poderá ser objeto de emenda tendente a abolir o voto popular, a separação dos Poderes ou os direitos e garantias fundamentais."},{"article_number":"Art. 68.","sort_order":30,"body":"Também são protegidos contra abolição os princípios fundamentais da República, a forma republicana e presidencialista de governo, a chefia de Estado e de Governo exercida pelo Presidente e a independência do Poder Judiciário, conforme os princípios estabelecidos nesta Constituição."},{"article_number":"Art. 69.","sort_order":40,"body":"Nenhum direito ou garantia fundamental previsto nesta Constituição poderá ser suprimido por emenda constitucional."}]},{"title":"TÍTULO XVII — DAS DISPOSIÇÕES FINAIS","sort_order":170,"articles":[{"article_number":"Art. 70.","sort_order":10,"body":"Esta Constituição entra em vigor na data de sua promulgação ou publicação oficial no GOV.RP, revogadas as disposições internas em contrário.\nParágrafo único. Esta Constituição orienta o funcionamento institucional do GOV.RP e deverá ser observada por todos os Poderes, órgãos públicos, partidos e autoridades."}]}]$govrp_document_json$::jsonb;
BEGIN
  INSERT INTO public.country_constitutions
    (country_code,version,title,preamble,closing_text,status,source_url,effective_at)
  VALUES
    ('BR','2.0','CONSTITUIÇÃO UNIFICADA DO GOV.RP','Nós, representantes e cidadãos do GOV.RP, reunidos sob a vontade soberana do povo, com o propósito de organizar o Estado, assegurar a liberdade, a justiça, a igualdade, a segurança e o bem-estar, proteger os direitos fundamentais e estabelecer o equilíbrio entre os Poderes, promulgamos, sob a proteção de Deus, esta Constituição como fundamento da ordem política, institucional, econômica e social da República.',
     'Promulgada para reger a vida política, institucional, econômica e social do GOV.RP.
“Ordem, Justiça e Liberdade.”','active','/constituicao-govrp.pdf',clock_timestamp())
  ON CONFLICT(country_code,version) DO UPDATE SET
    title=EXCLUDED.title,preamble=EXCLUDED.preamble,closing_text=EXCLUDED.closing_text,
    status='active',source_url=EXCLUDED.source_url,superseded_at=NULL,updated_at=clock_timestamp()
  RETURNING id INTO v_id;

  DELETE FROM public.constitution_sections WHERE constitution_id=v_id;

  FOR v_section IN SELECT value FROM jsonb_array_elements(v_sections)
  LOOP
    INSERT INTO public.constitution_sections(constitution_id,title,sort_order)
      VALUES(v_id,v_section->>'title',(v_section->>'sort_order')::integer)
      RETURNING id INTO v_section_id;
    FOR v_article IN SELECT value FROM jsonb_array_elements(v_section->'articles')
    LOOP
      INSERT INTO public.constitution_articles(section_id,article_number,body,sort_order)
      VALUES(v_section_id,v_article->>'article_number',v_article->>'body',(v_article->>'sort_order')::integer);
    END LOOP;
  END LOOP;
  IF (SELECT count(*) FROM public.constitution_sections WHERE constitution_id=v_id)<>17
     OR (SELECT count(*) FROM public.constitution_articles a
         JOIN public.constitution_sections s ON s.id=a.section_id WHERE s.constitution_id=v_id)<>79
  THEN RAISE EXCEPTION 'Incompleta: a Constituição deve possuir 17 títulos e 79 dispositivos.'; END IF;
END;
$govrp_unified$;

-- Keep the existing public API and append the closing provision displayed in the PDF.
CREATE OR REPLACE FUNCTION public.get_country_constitution(p_country_code text DEFAULT 'BR')
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $govrp_rpc$
  SELECT jsonb_build_object(
    'id',constitution.id,'countryCode',constitution.country_code,
    'version',constitution.version,'title',constitution.title,'preamble',constitution.preamble,
    'closingText',constitution.closing_text,'effectiveAt',constitution.effective_at,
    'sourceUrl',constitution.source_url,
    'sections',coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id',section.id,'title',section.title,'sortOrder',section.sort_order,
        'articles',coalesce((
          SELECT jsonb_agg(jsonb_build_object(
            'id',article.id,'number',article.article_number,'body',article.body,
            'sortOrder',article.sort_order
          ) ORDER BY article.sort_order,article.article_number)
          FROM public.constitution_articles article WHERE article.section_id=section.id
        ),'[]'::jsonb)
      ) ORDER BY section.sort_order,section.title)
      FROM public.constitution_sections section WHERE section.constitution_id=constitution.id
    ),'[]'::jsonb),
    'amendments',coalesce((
      SELECT jsonb_agg(to_jsonb(amendment) ORDER BY amendment.published_at)
      FROM public.constitution_amendments amendment WHERE amendment.constitution_id=constitution.id
    ),'[]'::jsonb)
  )
  FROM public.country_constitutions constitution
  WHERE constitution.country_code=upper(coalesce(nullif(p_country_code,''),'BR')) AND constitution.status='active'
  ORDER BY constitution.effective_at DESC LIMIT 1
$govrp_rpc$;
COMMIT;
